select eldervale_private.quest_arc_put('a3c0b000-0003-4000-8000-000000000004',$q${"chain":"arc-forge","order":4,"published":true,"objectives":[],"key":"arc-forge-4","name":"The Bellows Below","questPoints":3,"difficulty":"Experienced","length":"Long","giver":"a3c0a000-0003-4000-8000-000000000001","icon":"coal","requirements":{"quests":["arc-forge-3"],"qp":16,"skills":{"smithing":{"level":40,"boostable":false},"mining":{"level":40,"boostable":false},"firemaking":{"level":30,"boostable":false}}},"description":"Nix has been taken by the Kindled. Tamber needs an apprentice who knows the Anvilhall’s old channels, and Nix knows them better than he knows his own boots.","dialogue":{"offer":[{"who":"npc","text":"They took Nix. From the loft. In his nightshirt."},{"who":"npc","text":"Tamber wants the old channels. Nix sweeps them every week. He knows every grate between here and the scrubland."},{"who":"npc","text":"Bring him back. And find out where those channels lead. I will not be told the answer by a cult any longer."}],"progress":[{"who":"npc","text":"Nix? Anything? He owes me three weeks of sweeping."}],"complete":[{"who":"npc","text":"Nix! You stink of bellows-smoke and you are wearing one boot. Come here."},{"who":"npc","text":"The Kiln Door. Under the scrubland. A hundred years and not one forgemistress went down to look. That ends now. Take this, and the key."}]},"stages":[{"id":"trail","journal":"The Kindled took Nix the apprentice from the forge loft; Tamber wants his knowledge of the Anvilhall’s old heat channels. Kessa Emberly at the kiln camp east of Emberspire might know where he was taken.","objectives":[{"type":"talk","target":"a3c0a000-0003-4000-8000-000000000005","amount":1,"label":"Ask Kessa Emberly where Nix was taken","dialogue":[{"who":"npc","text":"They have him in the kiln camp, by the Kiln Door. Tamber wants the door open tonight and thinks Nix can read the old bellows."},{"who":"npc","text":"Two cinder-sworn guard him. I cannot fight them. You can."}]}]},{"id":"sworn","journal":"Nix is held in the kiln camp by two of Tamber’s cinder-sworn, who mean to make him open the Kiln Door tonight.","onEnter":{"cutscene":"camp"},"objectives":[{"type":"event","event":"death","targets":["a3c0a000-0003-4000-9000-000000000005","a3c0a000-0003-4000-9000-000000000006"],"amount":2,"label":"Defeat the cinder-sworn guards"}]},{"id":"bellows","journal":"Nix is free, and he says the Kiln Door is opened by three great bellows pumped in the order the Kindled pray. Kessa is the only one of us who has heard their prayers.","npc":"a3c0a000-0003-4000-8000-000000000005","objectives":[{"type":"talk","target":"a3c0a000-0003-4000-8000-000000000005","amount":1,"label":"Ask Kessa how the Kindled pray"}],"dialogue":{"choice":[{"who":"npc","text":"We pray to the fire’s life, as it was and will be. “The ember waits, the flame rises, the ash remembers.”"},{"who":"npc","text":"Three bellows: ember, flame, ash. Which order do you pump them?"}]},"choices":[{"id":"right","label":"Ember, then flame, then ash.","flags":{"door_opened":true},"next":"escort","dialogue":[{"who":"npc","text":"Listen. The door is breathing. It is open. Gods, it is warm down there."}]},{"id":"ash","label":"Ash, then ember, then flame.","next":"shrine-wall","dialogue":[{"who":"npc","text":"Nothing. The bellows just wheeze. The prayer is carved on the shrine wall; go and read it properly."}]},{"id":"flame","label":"Flame, then ash, then ember.","next":"shrine-wall","dialogue":[{"who":"npc","text":"A cough of soot, and nothing. The prayer is carved on the shrine wall; go and read it properly."}]}]},{"id":"shrine-wall","journal":"The bellows wheezed and the door stayed shut. Kessa says the Kindled prayer is carved on the wall of the Cinder Shrine; I should read it there and come back.","next":"bellows","objectives":[{"type":"visit","x":203,"z":146,"radius":3,"amount":1,"label":"Read the prayer on the Cinder Shrine wall"}]},{"id":"escort","journal":"The Kiln Door is breathing warm air. Before anyone goes down, Nix needs to get home to the Anvilhall in one piece, and he refuses to walk without an escort. Through the scrubland, by the old road.","onEnter":{"cutscene":"door"},"objectives":[{"type":"visit","x":292,"z":168,"radius":6,"amount":1,"label":"Walk Nix back along the old road"}]},{"id":"home","journal":"Nix and I reached the edge of Emberspire. He is limping on one boot and complaining about it at length. He should be safely back at the forge before I report to Kade.","objectives":[{"type":"talk","target":"a3c0a000-0003-4000-8000-000000000002","amount":1,"label":"See Nix safely back to the Anvilhall","dialogue":[{"who":"npc","text":"Home! My loft! My broom! I will never complain about sweeping again. That is a lie. But I will complain less."}]}]}],"cutscenes":{"camp":{"name":"The kiln camp","steps":[{"fade":"in","ms":700,"shot":{"around":"a3c0a000-0003-4000-8000-000000000005","distance":5,"height":2.2,"angle":30}},{"title":"The kiln camp","subtitle":"East of Emberspire","ms":2400},{"say":{"who":"npc","name":"Kessa Emberly","text":"Two of them, by the door. Nix is tied to the bellows. He is... lecturing them on correct bellows maintenance."},"shot":{"around":"a3c0a000-0003-4000-8000-000000000005","distance":3.4,"height":1.8,"angle":35}},{"fade":"out","ms":600}]},"door":{"name":"The Kiln Door","steps":[{"fade":"in","ms":700,"shot":{"around":"a3c0a000-0003-4000-8000-000000000005","distance":5,"height":2.2,"angle":30}},{"title":"The Kiln Door","subtitle":"The scrubland","ms":2400},{"say":{"who":"npc","name":"Kessa Emberly","text":"I will keep the camp quiet. Tamber is not here; he is already below. Whatever he is building, it is nearly done."},"shot":{"around":"a3c0a000-0003-4000-8000-000000000005","distance":3.4,"height":1.8,"angle":35}},{"fade":"out","ms":600}]},"nixhome":{"name":"One boot","steps":[{"fade":"in","ms":700,"shot":{"around":"a3c0a000-0003-4000-8000-000000000001","distance":5,"height":2.2,"angle":30}},{"title":"Home to the Anvilhall","subtitle":"Emberspire","ms":2400},{"say":{"who":"npc","name":"Forgemistress Oriel Kade","text":"The key to the Kiln Door has hung over my anvil for a hundred years. Today someone finally takes it down."},"shot":{"around":"a3c0a000-0003-4000-8000-000000000001","distance":3.4,"height":1.8,"angle":35}},{"fade":"out","ms":600}]}},"onComplete":{"cutscene":"nixhome"},"journalDone":"I freed Nix from the Kindled’s kiln camp, worked out the Kindled prayer that opens the Kiln Door, and walked Nix home. Forgemistress Kade has opened the way to the Kiln Below, where Tamber is finishing his Herald.","gold":1200,"xp":{"smithing":20000,"mining":15000,"firemaking":12000},"lamps":[{"amount":15000,"minLevel":30,"label":"Bellows lamp (any skill of level 30+)"}],"unlocks":[{"type":"area","id":"area.forge-kiln","label":"The Kiln Door, east of Emberspire"},{"type":"flag","id":"forge.kiln_door_open","label":"The Kiln Door breathes again"},{"type":"dialogue","id":"dialogue.forge-kessa-4","label":"Kessa keeps the camp","npc":"a3c0a000-0003-4000-8000-000000000005","lines":[{"who":"npc","text":"Half the Kindled went home after the camp. The other half are waiting to see what you do below. So am I."}]}]}$q$::jsonb);
select eldervale_private.quest_arc_put('a3c0b000-0003-4000-8000-000000000005',$q${"chain":"arc-forge","order":5,"published":true,"objectives":[],"key":"arc-forge-5","name":"The Emberwright’s Debt","questPoints":5,"difficulty":"Master","length":"Very long","giver":"a3c0a000-0003-4000-8000-000000000001","icon":"custom_qa_ember_seal","requirements":{"quests":["arc-forge-1","arc-forge-2","arc-forge-3","arc-forge-4"],"qp":34,"skills":{"smithing":{"level":50,"boostable":false},"mining":{"level":45,"boostable":false},"firemaking":{"level":45,"boostable":false}},"combat":65},"description":"Below the Kiln Door, Tamber’s Herald is ready to blow the Emberwright awake. Forgemistress Kade is going to settle a hundred-year debt one way or another.","dialogue":{"offer":[{"who":"npc","text":"A hundred years, and I am the forgemistress who has to pay. Fine. I would rather pay than steal."},{"who":"npc","text":"Nix is forging quench-chains for the Herald. Mithril, he says. He is very excited. Bring him the bars."},{"who":"npc","text":"Then go down and stop that golem before Tamber wakes the Emberwright angry."}],"progress":[{"who":"npc","text":"The anvils are cooling. I can feel it in the hammer. Hurry."}],"complete":[{"who":"npc","text":"The Herald’s heart. Still humming. And the Emberwright is... answered."},{"who":"npc","text":"The guild owes you more than it can pay. It will try. Take these gauntlets, sworn on the oldest anvil in Emberspire, and this seal."}]},"branchDialogue":[{"stage":"complete","ifFlags":{"rekindled":true},"lines":[{"who":"npc","text":"You let it wake. The anvils are colder and the Emberwright is free, and my guild has to learn to make its own heat."},{"who":"npc","text":"We will. It is about time. Take these gauntlets and this seal; the Kindled Forge below is open to you."}]},{"stage":"complete","ifFlags":{"bound":true},"lines":[{"who":"npc","text":"It sleeps again, by its own choice, and lends us its warmth as a gift instead of a theft. The guild will pay it back in kind, every year."},{"who":"npc","text":"Take these gauntlets and this seal; the Kindled Forge below is open to you."}]}],"stages":[{"id":"chains","journal":"Below the Kiln Door, Tamber’s Herald is nearly ready to blow the Emberwright awake. Nix wants two mithril bars to forge quench-chains to slow it down.","npc":"a3c0a000-0003-4000-8000-000000000002","objectives":[{"type":"collect","target":"mithrilBar","amount":2,"label":"Bring Nix two mithril bars"}],"dialogue":{"advance":[{"who":"npc","text":"Quench-chains! My first proper commission. Throw them at its bellows and it will sputter. In theory. Do not quote me."}]}},{"id":"below","journal":"Nix forged the quench-chains. Time to go down through the Kiln Door into the Kiln Below.","onEnter":{"cutscene":"below"},"objectives":[{"type":"visit","x":3022,"z":3000,"radius":7,"amount":1,"label":"Enter the bellows halls of the Kiln Below"}]},{"id":"guardians","journal":"The bellows halls are guarded by Kindled who gave the fire more than an oath.","objectives":[{"type":"event","event":"death","targets":["a3c0a000-0003-4000-9000-000000000007","a3c0a000-0003-4000-9000-000000000008"],"amount":2,"label":"Defeat the kiln-bound guardians"}]},{"id":"herald","journal":"In the crucible the Cinderbound Herald is pumping, louder every breath, and the floor is glowing. Tamber is nowhere to be seen; I think he climbed inside it.","onEnter":{"cutscene":"herald"},"objectives":[{"type":"kill","target":"a3c0a000-0003-4000-9000-000000000009","amount":1,"label":"Stop the Cinderbound Herald"},{"type":"have","target":"custom_qa_heart_coal","amount":1,"label":"Take the Herald’s heart-coal"}]},{"id":"ember","journal":"The Herald fell apart, and Tamber with it. In the quiet a voice like slow bellows spoke from the crucible floor: the Emberwright, half awake, wants to know what Emberspire will do now.","npc":"a3c0a000-0003-4000-8000-000000000006","objectives":[{"type":"talk","target":"a3c0a000-0003-4000-8000-000000000006","amount":1,"label":"Answer the Emberwright’s Ember","dialogue":[{"who":"npc","text":"Small one. A hundred years I have dreamed of hammers. Some of the dreams were pleasant."},{"who":"npc","text":"Your people drank from me without asking. Now you ask. So. What is it you ask?"}]}],"dialogue":{"choice":[{"who":"npc","text":"Shall I wake, and leave, and let your forges learn the cold? Or shall I sleep, and give you warmth, as a gift and not a theft?"}]},"choices":[{"id":"rekindle","label":"Wake and be free. Emberspire will learn to make its own fire.","flags":{"rekindled":true},"dialogue":[{"who":"npc","text":"Free. I had forgotten the word. I will remember your name, small one, for a while. A long while, for you."}]},{"id":"bind","label":"Sleep, and lend us your warmth; we will pay you back every year.","flags":{"bound":true},"dialogue":[{"who":"npc","text":"A gift. Yes. That is better than a chain. I will sleep warm, and your hammers will sing."}]}]},{"id":"debt","journal":"The Emberwright has its answer. The Herald’s heart-coal should go to Forgemistress Kade at the Anvilhall.","objectives":[{"type":"collect","target":"custom_qa_heart_coal","amount":1,"label":"Give the heart-coal to Forgemistress Kade"}]}],"cutscenes":{"below":{"name":"The Kiln Below","steps":[{"fade":"in","ms":700,"shot":{"around":"a3c0a000-0003-4000-8000-000000000005","distance":5,"height":2.2,"angle":30}},{"title":"The Kiln Below","subtitle":"Under the scrubland","ms":2400},{"say":{"who":"npc","name":"Kessa Emberly","text":"The Kindled who went below have not come back up. Be careful. Be quick. Be both."},"shot":{"around":"a3c0a000-0003-4000-8000-000000000005","distance":3.4,"height":1.8,"angle":35}},{"fade":"out","ms":600}]},"herald":{"name":"The Cinderbound Herald","steps":[{"fade":"in","ms":700,"shot":{"around":"a3c0a000-0003-4000-8000-000000000006","distance":5,"height":2.2,"angle":30}},{"title":"The Cinderbound Herald","subtitle":"The crucible","ms":2400},{"say":{"who":"npc","name":"The Emberwright’s Ember","text":"(Something huge stirs beneath the crucible floor, like a sleeper hearing its name.)"},"shot":{"around":"a3c0a000-0003-4000-8000-000000000006","distance":3.4,"height":1.8,"angle":35}},{"fade":"out","ms":600}]},"settled":{"name":"A debt settled","steps":[{"fade":"in","ms":700,"shot":{"around":"a3c0a000-0003-4000-8000-000000000002","distance":5,"height":2.2,"angle":30}},{"title":"The debt is settled","subtitle":"The Anvilhall, Emberspire","ms":2400},{"say":{"who":"npc","name":"Nix Calloway","text":"The Kindled Forge below is open to us now. Real anvils, real heat, honestly given. I may cry. I may already be crying."},"shot":{"around":"a3c0a000-0003-4000-8000-000000000002","distance":3.4,"height":1.8,"angle":35}},{"fade":"out","ms":600}]}},"onComplete":{"cutscene":"settled"},"journalDone":"Beneath the Kiln Door I broke the Kindled’s guardians and destroyed the Cinderbound Herald, with Tamber inside it. The Emberwright woke enough to ask what Emberspire would do, and I answered for the town. The Kindled Forge below is open to me, and an Emberwright’s Seal will always bring me back to the Anvilhall.","journalVariants":[{"ifFlags":{"rekindled":true},"text":"I let the Emberwright wake and go free; Emberspire is learning to make its own fire."},{"ifFlags":{"bound":true},"text":"The Emberwright chose to sleep and lend its warmth as a gift, repaid every year."}],"gold":5000,"xp":{"smithing":60000,"mining":40000,"firemaking":35000,"strength":30000},"items":{"custom_qa_ember_seal":1,"armor:emberOathGauntlets":1},"lamps":[{"amount":20000,"minLevel":40,"label":"Emberwright lamp (any skill of level 40+)"}],"unlocks":[{"type":"teleport","id":"teleport.anvilhall","label":"Emberwright’s Seal: the Anvilhall, Emberspire","x":264,"z":200},{"type":"area","id":"area.forge-kindled","label":"The Kindled Forge: anvil, furnace, rare-stock quartermaster and the Herald Reforged (harder mode)"},{"type":"area","id":"lair:cindervault_crucible","label":"The Cindervault crucible: the Ashen Colossus stirs in sympathy"},{"type":"flag","id":"forge.debt_settled","label":"Emberspire’s debt is settled"},{"type":"dialogue","id":"dialogue.forge-kade-wake","label":"Kade learns the cold","npc":"a3c0a000-0003-4000-8000-000000000001","ifFlags":{"rekindled":true},"lines":[{"who":"npc","text":"Our forges burn coal now, like everyone else’s. Slower. Honest. My blades have never been better, which is annoying."}]},{"type":"dialogue","id":"dialogue.forge-kade-gift","label":"Kade pays the gift back","npc":"a3c0a000-0003-4000-8000-000000000001","ifFlags":{"bound":true},"lines":[{"who":"npc","text":"Every midsummer the guild carries the year’s first blade down to the Emberwright. It hums when we arrive. I think it likes the company."}]},{"type":"dialogue","id":"dialogue.forge-kessa-5","label":"Kessa leads the Kindled","npc":"a3c0a000-0003-4000-8000-000000000005","lines":[{"who":"npc","text":"The Kindled tend the shrine fire now, and nothing else. No salt. No golems. Just a fire, and a debt remembered."}]},{"type":"dialogue","id":"dialogue.forge-pike-5","label":"Pike’s readings","npc":"a3c0a000-0003-4000-8000-000000000004","lines":[{"who":"npc","text":"The vents read steady. The deep shaft at Cindervault, though, reads hotter every day. Something down there felt the Emberwright stir."}]}]}$q$::jsonb);

commit;
